mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "status": {"type": "string", "description": "Only alerts in this status, e.g. 未対応. Empty or missing for all."}
  }
}

set-variable.value:
#[do {
            var raw = trim(payload.alertId default '')
            var digits = raw replace /^(?i)SV-?/ with ''
            ---
            if (digits matches /\d{1,4}/) 'SV-' ++ ((digits as Number) as String {format: '0000'}) else raw}]

mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "contextId": {"type": "string", "description": "The conversation (A2A contextId)"},
    "alertId": {"type": "string", "description": "Alert ID such as SV-0001"},
    "recommendation": {"type": "string", "enum": ["問題なし", "深掘り", "保留", "当局報告"]},
    "facts": {"type": "string", "description": "The alert, the customer and the announcement, 3 to 5 lines"},
    "notableTrades": {"type": "string", "description": "Related trades, one per line"},
    "relations": {"type": "string", "description": "Insider registry entries and the customer's link to the issuer"},
    "similarCases": {"type": "string", "description": "Similar past cases, one per line"},
    "gaps": {"type": "string", "description": "What could not be checked"},
    "reasoning": {"type": "string", "description": "Why this recommendation, 2 to 4 sentences"}
  },
  "required": ["contextId", "alertId", "recommendation", "facts", "reasoning"]
}
